["windows/tip/tipcore.cpp", "bool Core::OnKey(const Key& k) {\n    if (script_ == 6) return OnKeyEn(k);", "// ------------------------------------------------------------------------------------------------------------------------------------------ Phonetic IPA (script 4)\n// Every key that has look-alike symbols (IPA, extIPA, IAST) shows them as a one-key choice list: the key itself first. A digit takes one of them, Tab / the arrows move,\n// Enter and Esc keep the highlighted one (Esc: the plain key), Backspace drops it, Space and any other key keep it and go on. A symbol is typed as it is: no space, nothing learned.\nstatic bool PhKey(const Key& k) { return !k.ctrl && !k.alt && !k.win && k.ch > 32 && k.ch < 127; }\nbool Core::PhStart(const Key& k) {\n    std::vector<ustr> l;\n    if (!eng_ || !PhKey(k) || !eng_->PhonList(ustr(1, k.ch), l) || l.size() < 2) return false;\n    buf_ = ustr(1, k.ch); cands_ = l; sel_ = 0;\n    doc_->Compose(cands_[0]);\n    eng_->ShowList(cands_, sel_, buf_);\n    return true;\n}\nvoid Core::CommitPh(int idx, char16_t after) {\n    if (buf_.empty()) return;\n    ustr sym = (idx >= 0 && idx < (int)cands_.size()) ? cands_[idx] : buf_;\n    if (after) sym += after;\n    doc_->Commit(sym);\n    prev_ = u\"<s>\";\n    buf_.clear(); cands_.clear(); sel_ = 0;\n    if (eng_) eng_->HideList();\n}\nstatic bool PhDigitPick(const Key& k, const ustr& buf) {\n    return !k.shift && !k.ctrl && !k.alt && !k.win && k.ch >= u'1' && k.ch <= u'9' && !(buf.size() == 1 && buf[0] >= u'0' && buf[0] <= u'9');\n}\nbool Core::WouldEatPh(const Key& k) const {\n    if (buf_.empty()) {\n        std::vector<ustr> l;\n        return eng_ && PhKey(k) && eng_->PhonList(ustr(1, k.ch), l) && l.size() >= 2;\n    }\n    if (PhDigitPick(k, buf_) && (sel_ / kPageSize) * kPageSize + (int)(k.ch - u'1') < (int)cands_.size()) return true;\n    switch (Classify(k)) {\n        case Cls::Tab: case Cls::ShTab: case Cls::Up: case Cls::Down: case Cls::Enter: case Cls::Esc: case Cls::Bksp: case Cls::Space: return true;\n        case Cls::PgUp: case Cls::PgDn: return (int)cands_.size() > kPageSize;\n        default: break;\n    }\n    return PhKey(k);                                          // another symbol key: this one is kept and that one goes on\n}\nbool Core::OnKeyPh(const Key& k) {\n    if (buf_.empty()) return PhStart(k);\n    if (PhDigitPick(k, buf_)) {\n        int i = (sel_ / kPageSize) * kPageSize + (int)(k.ch - u'1');\n        if (i < (int)cands_.size()) { CommitPh(i, 0); return true; }\n    }\n    int n = (int)cands_.size();\n    switch (Classify(k)) {\n        case Cls::Tab: case Cls::Down: sel_ = (sel_ + 1) % n; doc_->Compose(cands_[sel_]); if (eng_) eng_->ShowList(cands_, sel_, buf_); return true;\n        case Cls::ShTab: case Cls::Up: sel_ = (sel_ + n - 1) % n; doc_->Compose(cands_[sel_]); if (eng_) eng_->ShowList(cands_, sel_, buf_); return true;\n        case Cls::PgUp: case Cls::PgDn: {\n            int pages = (n + kPageSize - 1) / kPageSize, p = sel_ / kPageSize;\n            if (pages > 1) { p = Classify(k) == Cls::PgDn ? (p + 1) % pages : (p + pages - 1) % pages; sel_ = p * kPageSize; doc_->Compose(cands_[sel_]); if (eng_) eng_->ShowList(cands_, sel_, buf_); return true; }\n            CommitPh(sel_, 0); return false;\n        }\n        case Cls::Enter: CommitPh(sel_, 0); return true;\n        case Cls::Esc: CommitPh(0, 0); return true;\n        case Cls::Bksp: buf_.clear(); cands_.clear(); sel_ = 0; doc_->EndEmpty(); if (eng_) eng_->HideList(); return true;\n        case Cls::Space: CommitPh(sel_, u' '); return true;\n        default: break;\n    }\n    if (PhKey(k)) {\n        CommitPh(sel_, 0);\n        if (!PhStart(k)) doc_->Commit(ustr(1, k.ch));\n        return true;\n    }\n    CommitPh(sel_, 0);                                         // an arrow, Delete, a chord ...: the symbol stays, the key goes on\n    return false;\n}\n\nbool Core::OnKey(const Key& k) {\n    if (script_ == 6) return OnKeyEn(k);\n    if (script_ == 4) return OnKeyPh(k);"],
