["windows/tip/tip.cpp", "    void Learn(int script, const sk::ustr& roman, const sk::ustr& word) override {\n", "    // Phonetic IPA: the symbols that look like the key (the key itself first), asked from the Sulekhak program once per key and kept\n    bool PhonList(const sk::ustr& key, std::vector<sk::ustr>& out) override {\n        auto it = phonCache_.find(key);\n        if (it != phonCache_.end()) { out = it->second; return !out.empty(); }\n        std::string r;\n        if (!Call(\"M\\t\" + ToUtf8(key), r) || r.empty() || r[0] != 'C') return false;     // not reachable, or the symbol lists are not loaded yet: asked again at the next key\n        out.clear();\n        size_t p = 2;\n        while (p <= r.size() && r.size() > 1) {\n            size_t e = r.find('\\t', p);\n            if (e == std::string::npos) e = r.size();\n            if (e > p) out.push_back(FromUtf8(r.data() + p, (int)(e - p)));\n            p = e + 1;\n        }\n        phonCache_[key] = out;\n        return !out.empty();\n    }\n    std::map<sk::ustr, std::vector<sk::ustr>> phonCache_;\n    void Learn(int script, const sk::ustr& roman, const sk::ustr& word) override {\n"],
