["windows/tip/tip.cpp", "    bool CtrlAltDigit(UINT vk, bool test, const char* via) {\n", "    // Ctrl+Alt+4 (Marathi ळ) and Ctrl+Alt+5 (anusvara instead of conjuncts) work on Devanagari, so the keyboard goes to Devanagari with the option turned over.\n    void ToggleDevanagariOption(int bit) {\n        FlushComposition();\n        int base = core_.Script() == 1 ? eng_.opt : (homeScript_ == 1 ? homeOpt_ : 0);\n        if (all_) { int s0 = 0, o0 = 0; if (eng_.FetchScript(&s0, &o0)) base = o0; }\n        int o = (base ^ bit) & 3;\n        eng_.opt = o; core_.SetScript(1);\n        if (all_) eng_.SetScript(1, o);                 // the Sulekhak program shows it in its menu\n    }\n    bool CtrlAltDigit(UINT vk, bool test, const char* via) {\n"],
