["windows/tip/tip.cpp", "void TsfDoc::CaretRect(RECT* rc) {\n", "bool TsfDoc::Surround(char16_t open, bool test) {\n    ITfRange* s = SelectionRange();\n    if (!s) return false;\n    BOOL empty = TRUE;\n    if (FAILED(s->IsEmpty(ec, &empty)) || empty) { s->Release(); return false; }\n    WCHAR buf[4000]; ULONG cch = 0;\n    if (FAILED(s->GetText(ec, 0, buf, 3990, &cch)) || cch == 0 || cch >= 3990) { s->Release(); return false; }\n    if (test) { s->Release(); return true; }\n    char16_t close = open == u'(' ? u')' : open == u'[' ? u']' : open == u'{' ? u'}' : open == u'<' ? u'>' : open;\n    sk::ustr w; w += open; w.append((const char16_t*)buf, cch); w += close;\n    if (FAILED(s->SetText(ec, 0, (const WCHAR*)w.data(), (LONG)w.size()))) { s->Release(); return false; }\n    LONG moved = 0;\n    s->ShiftStart(ec, 1, &moved, nullptr);              // select the text again, inside the pair\n    s->ShiftEnd(ec, -1, &moved, nullptr);\n    TF_SELECTION ts; ts.range = s; ts.style.ase = TF_AE_END; ts.style.fInterimChar = FALSE;\n    ctx->SetSelection(ec, 1, &ts);\n    s->Release();\n    return true;\n}\nvoid TsfDoc::CaretRect(RECT* rc) {\n"],
