["windows/App.cs", "        readonly ToolStripMenuItem[] miScript = new ToolStripMenuItem[7];\n", "        readonly ToolStripMenuItem[] miScript = new ToolStripMenuItem[7];\n        ToolStripMenuItem miMar, miAnu;\n        static readonly Font menuReg = new Font(SystemFonts.MenuFont, FontStyle.Regular), menuBold = new Font(SystemFonts.MenuFont, FontStyle.Bold);\n        // A choice shows a clear marker before its text (the small tick of the menu is hard to see, and a dark menu hides it): ● chosen, ○ not chosen; a switch shows ☑ on, ☐ off. What is chosen is bold too.\n        static void Mark(ToolStripMenuItem mi, bool on, bool radio)\n        {\n            string label = mi.Tag as string ?? mi.Text;\n            mi.Tag = label; mi.Checked = false;\n            mi.Text = (radio ? (on ? \"●  \" : \"○  \") : (on ? \"☑  \" : \"☐  \")) + label;\n            mi.Font = on ? menuBold : menuReg;\n        }\n        void SetDvOpts(int o)                    // chosen with Ctrl+Alt+4 / 5 in the text service\n        {\n            o &= 3; if (o == dvOpts) return;\n            dvOpts = o; SaveSetting(\"Opts\", dvOpts);\n            if (host != null) host.SetScript(script, dvOpts);\n            UpdateTray();\n        }\n"],
